from oumi.inference import VLLMInferenceEngine
from oumi.core.configs import InferenceConfig, ModelParams, GenerationParams
from oumi.core.types.conversation import Conversation, Message, Role, ContentItem, Type

# Initialize engine
engine = VLLMInferenceEngine(
    model_params=ModelParams(
        model_name="../train/saved_model/tool_thinker-0.1",
        torch_dtype_str="bfloat16"
    )
)

# Create a conversation with system and user messages
